SELECT COUNT(DISTINCT r.id) FROM chat_room r
JOIN chat_room_participants p ON p.chatroom_id = r.id
WHERE p.userprofile_id = #{profileId}

SELECT  FROM chat_room r

ORDER BY COALESCE(lm.created_at, r.updated_at) DESC
LIMIT #{limit} OFFSET #{offset}

SELECT r.id FROM chat_room r
JOIN chat_room_participants p1 ON p1.chatroom_id = r.id
    AND p1.userprofile_id = #{firstProfileId}
JOIN chat_room_participants p2 ON p2.chatroom_id = r.id
    AND p2.userprofile_id = #{secondProfileId}
WHERE r.room_type = 'private' ORDER BY r.updated_at DESC LIMIT 1

